/* DAWAH X — ahmad, অধ্যায় 62 · খণ্ড 62 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][62]=[[12201,12201,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَقْوَامًا سَيَخْرُجُونَ مِنْ النَّارِ قَدْ أَصَابَهُمْ ‏ ‏سَفْعٌ ‏ ‏مِنْ النَّارِ عُقُوبَةً بِذُنُوبٍ عَمِلُوهَا لِيُخْرِجَهُمْ اللَّهُ بِفَضْلِ رَحْمَتِهِ فَيَدْخُلُونَ الْجَنَّةَ ‏","","",""],[12202,12202,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏فَزِعَ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مَرَّةً ‏ ‏فَرَكِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا كَأَنَّهُ ‏ ‏مُقْرِفٌ ‏ ‏فَرَكَضَهُ ‏ ‏فِي آثَارِهِمْ فَلَمَّا رَجَعَ قَالَ وَجَدْنَاهُ بَحْرًا ‏","","",""],[12203,12203,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ ‏","","",""],[12204,12204,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏إِنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِلْقُرْآنِ ‏","","",""],[12205,12205,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ اشْتَكَى ‏ ‏فَأَمَرَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَصَلَّى لِلنَّاسِ فَكَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُتْرَةَ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏فَنَظَرَ إِلَى النَّاسِ فَنَظَرْتُ إِلَى وَجْهِهِ كَأَنَّهُ وَرَقَةُ مُصْحَفٍ حَتَّى ‏ ‏نَكَصَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَلَى عَقِبَيْهِ لِيَصِلَ إِلَى الصَّفِّ وَظَنَّ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ أَنْ يُصَلِّيَ لِلنَّاسِ فَتَبَسَّمَ حِينَ رَآهُمْ صُفُوفًا وَأَشَارَ بِيَدِهِ إِلَيْهِمْ أَنْ أَتِمُّوا صَلَاتَكُمْ وَأَرْخَى السِّتْرَ بَيْنَهُ وَبَيْنَهُمْ فَتُوُفِّيَ مِنْ يَوْمِهِ ذَلِكَ ‏","","",""],[12206,12206,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏قَتَلَ ‏ ‏جَارِيَةً ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَى حُلِيٍّ لَهَا ثُمَّ أَلْقَاهَا فِي ‏ ‏قَلِيبٍ ‏ ‏وَرَضَخَ ‏ ‏رَأْسَهَا بِالْحِجَارَةِ فَأُخِذَ فَأُتِيَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِهِ أَنْ ‏ ‏يُرْجَمَ ‏ ‏حَتَّى يَمُوتَ ‏ ‏فَرُجِمَ ‏ ‏حَتَّى مَاتَ ‏","","",""],[12207,12207,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَفَرًا مِنْ ‏ ‏عُكْلٍ ‏ ‏وَعُرَيْنَةَ ‏ ‏تَكَلَّمُوا بِالْإِسْلَامِ فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرُوهُ أَنَّهُمْ أَهْلُ ضَرْعٍ وَلَمْ يَكُونُوا أَهْلَ رِيفٍ وَشَكَوْا ‏ ‏حُمَّى ‏ ‏الْمَدِينَةِ ‏ ‏فَأَمَرَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَوْدٍ ‏ ‏وَأَمَرَهُمْ أَنْ يَخْرُجُوا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَيَشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَانْطَلَقُوا فَكَانُوا فِي نَاحِيَةِ ‏ ‏الْحَرَّةِ ‏ ‏فَكَفَرُوا بَعْدَ إِسْلَامِهِمْ وَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَاقُوا ‏ ‏الذَّوْدَ ‏ ‏فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَ الطَّلَبَ فِي آثَارِهِمْ فَأُتِيَ بِهِمْ ‏ ‏فَسَمَلَ ‏ ‏أَعْيُنَهُمْ وَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ وَتُرِكُوا بِنَاحِيَةِ ‏ ‏الْحَرَّةِ ‏ ‏يَقْضَمُونَ حِجَارَتَهَا حَتَّى مَاتُوا ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَبَلَغَنَا أَنَّ هَذِهِ الْآيَةَ نَزَلَتْ فِيهِمْ ‏ { ‏إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ ‏}","","",""],[12208,12208,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا تَزَوَّجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏ ‏أَهْدَتْ إِلَيْهِ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏حَيْسًا ‏ ‏فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ حِجَارَةٍ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاذْهَبْ فَادْعُ مَنْ لَقِيتَ فَجَعَلُوا يَدْخُلُونَ يَأْكُلُونَ وَيَخْرُجُونَ وَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَلَى الطَّعَامِ وَدَعَا فِيهِ وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ ‏ ‏وَلَمْ أَدَعْ أَحَدًا لَقِيتُهُ إِلَّا دَعَوْتُهُ فَأَكَلُوا حَتَّى شَبِعُوا وَخَرَجُوا فَبَقِيَتْ طَائِفَةٌ مِنْهُمْ فَأَطَالُوا عَلَيْهِ الْحَدِيثَ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَحِي مِنْهُمْ أَنْ يَقُولَ لَهُمْ شَيْئًا فَخَرَجَ وَتَرَكَهُمْ فِي الْبَيْتِ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ ‏ ‏إِنَاهُ ‏ ‏وَلَكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا ‏ ‏حَتَّى بَلَغَ ‏ ‏لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ‏}","","",""],[12209,12209,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏صَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏بُكْرَةً ‏ ‏وَقَدْ خَرَجُوا ‏ ‏بِالْمَسَاحِي ‏ ‏فَلَمَّا نَظَرُوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَيْهِ وَقَالَ ‏ ‏اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏","","",""],[12210,12210,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏فَوَجَدَهُمْ حِينَ خَرَجُوا إِلَى زُرُوعِهِمْ وَمَعَهُمْ ‏ ‏مَسَاحِيهِمْ ‏ ‏فَلَمَّا رَأَوْهُ وَمَعَهُ الْجَيْشُ نَكَصُوا فَرَجَعُوا إِلَى حِصْنِهِمْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏","","",""],[12211,12211,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِالْبُرَاقِ ‏ ‏لَيْلَةَ أُسْرِيَ بِهِ مُسَرَّجًا مُلَجَّمًا لِيَرْكَبَهُ فَاسْتَصْعَبَ عَلَيْهِ وَقَالَ لَهُ ‏ ‏جِبْرِيلُ ‏ ‏مَا يَحْمِلُكَ عَلَى هَذَا فَوَاللَّهِ مَا رَكِبَكَ أَحَدٌ قَطُّ أَكْرَمُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْهُ قَالَ ‏ ‏فَارْفَضَّ ‏ ‏عَرَقًا ‏","","",""],[12212,12212,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُفِعَتْ لِي ‏ ‏سِدْرَةُ الْمُنْتَهَى ‏ ‏فِي السَّمَاءِ السَّابِعَةِ ‏ ‏نَبْقُهَا ‏ ‏مِثْلُ ‏ ‏قِلَالِ ‏ ‏هَجَرَ ‏ ‏وَوَرَقُهَا مِثْلُ آذَانِ الْفِيَلَةِ يَخْرُجُ مِنْ سَاقِهَا نَهْرَانِ ظَاهِرَانِ وَنَهْرَانِ بَاطِنَانِ فَقُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذَانِ قَالَ أَمَّا الْبَاطِنَانِ فَفِي الْجَنَّةِ وَأَمَّا الظَّاهِرَانِ فَالنِّيلُ وَالْفُرَاتُ ‏","","",""],[12213,12213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ أَحَدٌ أَشْبَهَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏وَفَاطِمَةَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏ ‏أَجْمَعِينَ ‏","","",""],[12214,12214,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ‏} ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هُوَ نَهَرٌ فِي الْجَنَّةِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ نَهْرًا فِي الْجَنَّةِ حَافَّتَاهُ ‏ ‏قِبَابُ ‏ ‏اللُّؤْلُؤِ فَقُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[12215,12215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ فَإِنْ لَمْ يَكُنْ رُطَبَاتٌ فَتَمَرَاتٌ فَإِنْ لَمْ يَكُنْ تَمَرَاتٌ ‏ ‏حَسَا ‏ ‏حَسَوَاتٍ ‏ ‏مِنْ مَاءٍ ‏","","",""],[12216,12216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَظِلٍّ مَمْدُودٍ ‏} ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏وَظِلٍّ مَمْدُودٍ ‏}","","",""],[12217,12217,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَهُوَ يُسَايِرُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ رِجْلِي لَتَمَسُّ ‏ ‏غَرَزَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ ‏ ‏يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ مَعًا ‏","","",""],[12218,12218,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ مُنَادِيَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَادَى إِنَّ اللَّهَ وَرَسُولَهُ ‏ ‏يَنْهَيَانِكُمْ عَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏","","",""],[12219,12219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ جَدَّتَهُ ‏ ‏مُلَيْكَةَ ‏ ‏دَعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِطَعَامٍ صَنَعَتْهُ لَهُ قَالَ فَأَكَلَ ثُمَّ قَالَ ‏ ‏قُومُوا فَلِأُصَلِّيَ لَكُمْ قَالَ فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدْ اسْوَدَّ مِنْ طُولِ مَا لَبِثَ ‏ ‏فَنَضَحْتُهُ ‏ ‏بِمَاءٍ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَفَفْتُ أَنَا ‏ ‏وَالْيَتِيمُ ‏ ‏وَرَاءَهُ وَالْعَجُوزُ وَرَاءَنَا فَصَلَّى لَنَا رَكْعَتَيْنِ ثُمَّ انْصَرَفَ ‏","","",""],[12220,12220,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏يَوْمَ الْفَتْحِ وَعَلَيْهِ ‏ ‏الْمِغْفَرُ ‏ ‏فَجَاءَ رَجُلٌ فَقَالَ ‏ ‏هَذَا ‏ ‏ابْنُ خَطَلٍ ‏ ‏مُتَعَلِّقٌ بِالْأَسْتَارِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهُ ‏","","",""],[12221,12221,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ وَهُوَ مُحْرِمٌ عَلَى ظَهْرِ الْقَدَمِ مِنْ وَجَعٍ كَانَ بِهِ ‏","","",""],[12222,12222,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَعْمَالَكُمْ تُعْرَضُ عَلَى أَقَارِبِكُمْ وَعَشَائِرِكُمْ مِنْ الْأَمْوَاتِ فَإِنْ كَانَ خَيْرًا اسْتَبْشَرُوا بِهِ وَإِنْ كَانَ غَيْرَ ذَلِكَ قَالُوا اللَّهُمَّ لَا تُمِتْهُمْ حَتَّى تَهْدِيَهُمْ كَمَا هَدَيْتَنَا ‏","","",""],[12223,12223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[12224,12224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏وَبِهِ ‏ ‏وَضَرٌ ‏ ‏مِنْ ‏ ‏خَلُوقٍ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْيَمْ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏قَالَ تَزَوَّجْتُ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ كَمْ ‏ ‏أَصْدَقْتَهَا ‏ ‏قَالَ وَزْنَ نَوَاةٍ مِنْ ذَهَبٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْلِمْ ‏ ‏وَلَوْ بِشَاةٍ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏لَقَدْ رَأَيْتُهُ قَسَمَ لِكُلِّ امْرَأَةٍ مِنْ نِسَائِهِ بَعْدَ مَوْتِهِ مِائَةَ أَلْفِ دِينَارٍ ‏","","",""],[12225,12225,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَأَبَانَ ‏ ‏وَغَيْرِ وَاحِدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[12226,12226,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[12227,12227,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏سَأَلَ أَهْلُ ‏ ‏مَكَّةَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آيَةً فَانْشَقَّ الْقَمَرُ ‏ ‏بِمَكَّةَ ‏ ‏مَرَّتَيْنِ فَقَالَ ‏ { ‏اقْتَرَبَتْ السَّاعَةُ وَانْشَقَّ الْقَمَرُ وَإِنْ يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ ‏}","","",""],[12228,12228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانَ الْفُحْشُ فِي شَيْءٍ قَطُّ إِلَّا شَانَهُ وَلَا كَانَ الْحَيَاءُ فِي شَيْءٍ قَطُّ إِلَّا زَانَهُ ‏","","",""],[12229,12229,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا عَدَدْتُ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِحْيَتِهِ إِلَّا أَرْبَعَ عَشْرَةَ شَعَرَةً بَيْضَاءَ ‏","","",""],[12230,12230,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحَاسَدُوا وَلَا تَقَاطَعُوا وَلَا تَدَابَرُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ ‏","","",""],[12231,12231,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَتَى السَّاعَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا أَعْدَدْتَ لَهَا فَقَالَ الْأَعْرَابِيُّ مَا أَعْدَدْتُ لَهَا مِنْ كَبِيرٍ أَحْمَدُ عَلَيْهِ نَفْسِي إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12232,12232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ شَعَرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[12233,12233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَظَرَ بَعْضُ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءًا فَلَمْ يَجِدُوا قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَاهُنَا مَاءٌ قَالَ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضَعَ يَدَهُ فِي الْإِنَاءِ الَّذِي فِيهِ الْمَاءُ ثُمَّ قَالَ تَوَضَّئُوا بِسْمِ اللَّهِ فَرَأَيْتُ الْمَاءَ يَفُورُ ‏ ‏يَعْنِي بَيْنَ أَصَابِعِهِ ‏ ‏وَالْقَوْمُ يَتَوَضَّئُونَ حَتَّى تَوَضَّئُوا عَنْ آخِرِهِمْ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَمْ ‏ ‏تُرَاهُمْ كَانُوا قَالَ ‏ ‏نَحْوًا مِنْ سَبْعِينَ ‏","","",""],[12234,12234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَعَدَنِي أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي أَرْبَعَ مِائَةِ أَلْفٍ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏زِدْنَا يَا رَسُولَ اللَّهِ قَالَ وَهَكَذَا وَجَمَعَ كَفَّهُ قَالَ زِدْنَا يَا رَسُولَ اللَّهِ قَالَ وَهَكَذَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏حَسْبُكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏دَعْنِي يَا ‏ ‏عُمَرُ ‏ ‏مَا عَلَيْكَ أَنْ يُدْخِلَنَا اللَّهُ عَزَّ وَجَلَّ الْجَنَّةَ كُلَّنَا فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ إِنْ شَاءَ أَدْخَلَ خَلْقَهُ الْجَنَّةَ بِكَفٍّ وَاحِدٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏ ‏عُمَرُ ‏","","",""],[12235,12235,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏حِينَ ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ أَمْوَالَ ‏ ‏هَوَازِنَ ‏ ‏وَطَفِقَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِي رِجَالًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏الْمِائَةَ مِنْ الْإِبِلِ كُلَّ رَجُلٍ فَقَالُوا يَغْفِرُ اللَّهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِي ‏ ‏قُرَيْشًا ‏ ‏وَيَتْرُكُنَا وَسُيُوفُنَا تَقْطُرُ مِنْ دِمَائِهِمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَحُدِّثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَقَالَتِهِمْ فَأَرْسَلَ إِلَى ‏ ‏الْأَنْصَارِ ‏ ‏فَجَمَعَهُمْ فِي ‏ ‏قُبَّةٍ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏وَلَمْ يَدْعُ أَحَدًا غَيْرَهُمْ فَلَمَّا اجْتَمَعُوا جَاءَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا حَدِيثٌ بَلَغَنِي عَنْكُمْ فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏أَمَّا ذَوُو رَأْيِنَا فَلَمْ يَقُولُوا شَيْئًا وَأَمَّا نَاسٌ حَدِيثَةٌ أَسْنَانُهُمْ فَقَالُوا كَذَا وَكَذَا لِلَّذِي قَالُوا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأُعْطِي رِجَالًا حُدَثَاءَ عَهْدٍ بِكُفْرٍ ‏ ‏أَتَأَلَّفُهُمْ ‏ ‏أَوْ قَالَ ‏ ‏أَسْتَأْلِفُهُمْ ‏ ‏أَفَلَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالْأَمْوَالِ وَتَرْجِعُونَ بِرَسُولِ اللَّهِ إِلَى ‏ ‏رِحَالِكُمْ ‏ ‏فَوَاللَّهِ لَمَا تَنْقَلِبُونَ بِهِ خَيْرٌ مِمَّا يَنْقَلِبُونَ بِهِ قَالُوا أَجَلْ يَا رَسُولَ اللَّهِ قَدْ رَضِينَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَجِدُونَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏شَدِيدَةً فَاصْبِرُوا حَتَّى تَلْقَوْا اللَّهَ وَرَسُولَهُ فَإِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَلَمْ نَصْبِرْ ‏","","",""],[12236,12236,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَطْلُعُ عَلَيْكُمْ الْآنَ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَطَلَعَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَنْطِفُ ‏ ‏لِحْيَتُهُ مِنْ وُضُوئِهِ قَدْ تَعَلَّقَ نَعْلَيْهِ فِي يَدِهِ الشِّمَالِ فَلَمَّا كَانَ الْغَدُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ فَطَلَعَ ذَلِكَ الرَّجُلُ مِثْلَ الْمَرَّةِ الْأُولَى فَلَمَّا كَانَ الْيَوْمُ الثَّالِثُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ مَقَالَتِهِ أَيْضًا فَطَلَعَ ذَلِكَ الرَّجُلُ عَلَى مِثْلِ حَالِهِ الْأُولَى فَلَمَّا قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبِعَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏فَقَالَ إِنِّي لَاحَيْتُ أَبِي فَأَقْسَمْتُ أَنْ لَا أَدْخُلَ عَلَيْهِ ثَلَاثًا فَإِنْ رَأَيْتَ أَنْ تُؤْوِيَنِي إِلَيْكَ حَتَّى تَمْضِيَ فَعَلْتَ قَالَ نَعَمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُحَدِّثُ أَنَّهُ بَاتَ مَعَهُ تِلْكَ اللَّيَالِي الثَّلَاثَ فَلَمْ يَرَهُ يَقُومُ مِنْ اللَّيْلِ شَيْئًا غَيْرَ أَنَّهُ إِذَا ‏ ‏تَعَارَّ ‏ ‏وَتَقَلَّبَ عَلَى فِرَاشِهِ ذَكَرَ اللَّهَ عَزَّ وَجَلَّ وَكَبَّرَ حَتَّى يَقُومَ لِصَلَاةِ الْفَجْرِ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏غَيْرَ أَنِّي لَمْ أَسْمَعْهُ يَقُولُ إِلَّا خَيْرًا فَلَمَّا مَضَتْ الثَّلَاثُ لَيَالٍ وَكِدْتُ أَنْ أَحْتَقِرَ عَمَلَهُ قُلْتُ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏إِنِّي لَمْ يَكُنْ بَيْنِي وَبَيْنَ أَبِي غَضَبٌ وَلَا هَجْرٌ ثَمَّ وَلَكِنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَكَ ثَلَاثَ مِرَارٍ ‏ ‏يَطْلُعُ عَلَيْكُمْ الْآنَ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَطَلَعْتَ أَنْتَ الثَّلَاثَ مِرَارٍ فَأَرَدْتُ أَنْ ‏ ‏آوِيَ ‏ ‏إِلَيْكَ لِأَنْظُرَ مَا عَمَلُكَ فَأَقْتَدِيَ بِهِ فَلَمْ أَرَكَ تَعْمَلُ كَثِيرَ عَمَلٍ فَمَا الَّذِي بَلَغَ بِكَ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا هُوَ إِلَّا مَا رَأَيْتَ قَالَ فَلَمَّا وَلَّيْتُ دَعَانِي فَقَالَ مَا هُوَ إِلَّا مَا رَأَيْتَ غَيْرَ أَنِّي لَا أَجِدُ فِي نَفْسِي لِأَحَدٍ مِنْ الْمُسْلِمِينَ غِشًّا وَلَا أَحْسُدُ أَحَدًا عَلَى خَيْرٍ أَعْطَاهُ اللَّهُ إِيَّاهُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذِهِ الَّتِي بَلَغَتْ بِكَ وَهِيَ الَّتِي لَا نُطِيقُ ‏","","",""],[12237,12237,"","","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ بْنِ هِلَالِ بْنِ أَبِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏خَالِدٍ يَعْنِي الْحَذَّاءَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ سِيرِينَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏هَلْ ‏ ‏قَنَتَ ‏ ‏عُمَرُ ‏ ‏قَالَ نَعَمْ وَمَنْ هُوَ خَيْرٌ مِنْ ‏ ‏عُمَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الرُّكُوعِ ‏","","",""],[12238,12238,"","","‏ ‏حَدَّثَنَا ‏ ‏غَسَّانُ بْنُ مُضَرَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ يَزِيدَ أَبُو مَسْلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي النَّعْلَيْنِ قَالَ نَعَمْ ‏","","",""],[12239,12239,"","","‏ ‏حَدَّثَنَا ‏ ‏غَسَّانُ بْنُ مُضَرَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ يَزِيدَ أَبُو مَسْلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏أَوْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏فَقَالَ ‏ ‏إِنَّكَ لَتَسْأَلُنِي عَنْ شَيْءٍ مَا أَحْفَظُهُ أَوْ مَا سَأَلَنِي أَحَدٌ قَبْلَكَ ‏","","",""],[12240,12240,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ الْعَمِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ عَلَى نِسَائِهِ فِي لَيْلَةٍ وَاحِدَةٍ ‏","","",""],[12241,12241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[12242,12242,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ يَعْنِي الْمَقْبُرِيَّ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَحَذَّرَ النَّاسَ فَقَامَ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ مَتَى السَّاعَةُ يَا رَسُولَ اللَّهِ ‏ ‏فَبَسَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِهِ فَقُلْنَا لَهُ اقْعُدْ فَإِنَّكَ قَدْ سَأَلْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَكْرَهُ قَالَ ثُمَّ قَامَ الثَّانِيَةَ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ ‏ ‏فَبَسَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِهِ أَشَدَّ مِنْ الْأُولَى فَأَجْلَسْنَاهُ قَالَ ثُمَّ قَامَ الثَّالِثَةَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَتَى السَّاعَةُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَكَ ‏ ‏وَمَا أَعْدَدْتَ لَهَا قَالَ أَعْدَدْتُ لَهَا حُبَّ اللَّهِ وَرَسُولِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْلِسْ فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12243,12243,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏الرُّبَيِّعَ بِنْتَ النَّضْرِ ‏ ‏عَمَّةَ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏كَسَرَتْ ‏ ‏ثَنِيَّةَ ‏ ‏جَارِيَةٍ فَعَرَضُوا عَلَيْهِمْ ‏ ‏الْأَرْشَ ‏ ‏فَأَبَوْا وَطَلَبُوا الْعَفْوَ فَأَبَوْا فَأَبَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ ‏ ‏بِالْقِصَاصِ ‏ ‏فَجَاءَ أَخُوهَا ‏ ‏أَنَسُ بْنُ النَّضْرِ ‏ ‏عَمُّ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَتُكْسَرُ ‏ ‏ثَنِيَّةُ ‏ ‏الرُّبَيِّعِ ‏ ‏لَا وَالَّذِي بَعَثَكَ بِالْحَقِّ لَا تُكْسَرُ ‏ ‏ثَنِيَّتُهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏كِتَابُ اللَّهِ ‏ ‏الْقِصَاصُ ‏ ‏قَالَ فَعَفَا الْقَوْمُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ ‏ ‏لَأَبَرَّهُ ‏","","",""],[12244,12244,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُهُ عَنْ ‏ ‏الْقُنُوتِ ‏ ‏أَقَبْلَ الرُّكُوعِ أَوْ بَعْدَ الرُّكُوعِ فَقَالَ قَبْلَ الرُّكُوعِ قَالَ قُلْتُ فَإِنَّهُمْ يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏بَعْدَ الرُّكُوعِ فَقَالَ كَذَبُوا إِنَّمَا ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا يَدْعُو عَلَى نَاسٍ قَتَلُوا نَاسًا مِنْ أَصْحَابِهِ يُقَالُ لَهُمْ الْقُرَّاءُ ‏","","",""],[12245,12245,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏دَعَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَكْتُبَ لَنَا ‏ ‏بِالْبَحْرَيْنِ ‏ ‏قَطِيعَةً ‏ ‏قَالَ فَقُلْنَا لَا إِلَّا أَنْ تَكْتُبَ لِإِخْوَانِنَا مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِثْلَهَا فَقَالَ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي قَالُوا فَإِنَّا نَصْبِرُ ‏","","",""],[12246,12246,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ أَبِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عَاصِمٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏بِالْكُوفَةِ ‏ ‏فَسَأَلْتُهُ عَنْ ‏ ‏النَّبِيذِ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[12247,12247,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نُفَيْعٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ كَيْفَ يُحْشَرُ النَّاسُ عَلَى وُجُوهِهِمْ قَالَ ‏ ‏إِنَّ الَّذِي أَمْشَاهُمْ عَلَى أَرْجُلِهِمْ قَادِرٌ عَلَى أَنْ يُمْشِيَهُمْ عَلَى وُجُوهِهِمْ ‏","","",""],[12248,12248,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى حَاجَتَهُ ثُمَّ قَامَ إِلَى جَانِبِ الْمَسْجِدِ قَالَ فَصَاحَ بَعْضُ النَّاسِ فَكَفَّهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏أَمَرَ ‏ ‏بِذَنُوبٍ ‏ ‏مِنْ مَاءٍ فَصُبَّ عَلَى بَوْلِهِ ‏","","",""],[12249,12249,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏نُفَيْعٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَحَدٍ غَنِيٍّ وَلَا فَقِيرٍ إِلَّا يَوَدُّ يَوْمَ الْقِيَامَةِ أَنَّهُ كَانَ أُوتِيَ فِي الدُّنْيَا ‏ ‏قُوتًا ‏","","",""],[12250,12250,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ الْأَخْنَسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مُرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَدَنَةٍ ‏ ‏أَوْ هَدِيَّةٍ ‏ ‏فَقَالَ لِصَاحِبِهَا ‏ ‏ارْكَبْهَا فَقَالَ إِنَّهَا بَدَنَةٌ ‏ ‏أَوْ هَدِيَّةٌ ‏ ‏قَالَ وَإِنْ ‏","","",""],[12251,12251,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا فَكَمْ مَنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ ‏","","",""],[12252,12252,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَثَابِتٍ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَجُلًا جَاءَ وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ فَقَالَ ‏ ‏اللَّهُ أَكْبَرُ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ قَالَ أَيُّكُمْ الْمُتَكَلِّمُ ‏ ‏بِالْكَلِمَاتِ فَإِنَّهُ لَمْ يَقُلْ بَأْسًا فَقَالَ الرَّجُلُ أَنَا يَا رَسُولَ اللَّهِ جَلَسْتُ وَقَدْ ‏ ‏حَفَزَنِي ‏ ‏النَّفَسُ فَقُلْتُهُنَّ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا ‏ ‏يَبْتَدِرُونَهَا ‏ ‏أَيُّهُمْ يَرْفَعُهَا ‏","","",""],[12253,12253,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏وَثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقُرْآنَ ‏ ‏بِالْحَمْدِ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[12254,12254,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قِيَامِ السَّاعَةِ وَأُقِيمَتْ الصَّلَاةُ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ قَالَ ‏ ‏أَيْنَ السَّائِلُ عَنْ السَّاعَةِ فَقَالَ الرَّجُلُ هَا أَنَا ذَا يَا رَسُولَ اللَّهِ فَقَالَ وَمَا أَعْدَدْتَ لَهَا فَإِنَّهَا قَائِمَةٌ قَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَبِيرِ عَمَلٍ غَيْرَ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَأَنْتَ مَعَ مَنْ أَحْبَبْتَ قَالَ فَمَا فَرِحَ الْمُسْلِمُونَ بِشَيْءٍ بَعْدَ الْإِسْلَامِ أَشَدَّ مِمَّا فَرِحُوا بِهِ ‏","","",""],[12255,12255,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ الْأَنْصَارِيُّ ‏ ‏أَنَّهُ كَانَ ابْنَ عَشْرِ سِنِينَ مَقْدِمَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ وَكَانَ ‏ ‏أُمَّهَاتِي يُوطِئْنَنِي عَلَى خِدْمَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَعْلَمَ النَّاسِ بِشَأْنِ الْحِجَابِ حِينَ أُنْزِلَ وَكَانَ أَوَّلَ مَا أُنْزِلَ ‏ ‏ابْتَنَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَا عَرُوسًا فَدَعَا الْقَوْمَ فَأَصَابُوا مِنْ الطَّعَامِ ثُمَّ خَرَجُوا وَبَقِيَ ‏ ‏رَهْطٌ ‏ ‏مِنْهُمْ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَالُوا ‏ ‏الْمُكْثَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ وَخَرَجْتُ مَعَهُ لِكَيْ يَخْرُجُوا فَمَشَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَشَيْنَا مَعَهُ حَتَّى جَاءَ عَتَبَةَ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏وَظَنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ قَدْ خَرَجُوا فَرَجَعَ وَرَجَعْتُ مَعَهُ فَإِذَا هُمْ قَدْ خَرَجُوا فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُ وَبَيْنَهُمْ بِسِتْرٍ وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ الْحِجَابَ ‏","","",""],[12256,12256,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيًا مِنْ ذَهَبٍ لَأَحَبَّ أَنْ يَكُونَ لَهُ وَادٍ آخَرُ وَلَا يَمْلَأُ فَاهُ إِلَّا التُّرَابُ وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏","","",""],[12257,12257,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَكْعَتَيْنِ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَكْعَتَيْنِ ‏ ‏وَمَعَ ‏ ‏عُثْمَانَ ‏ ‏رَكْعَتَيْنِ ‏ ‏صَدْرًا ‏ ‏مِنْ ‏ ‏إِمَارَتِهِ ‏","","",""],[12258,12258,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُلُوسًا فِي الْمَسْجِدِ دَخَلَ رَجُلٌ عَلَى جَمَلٍ ‏ ‏فَأَنَاخَهُ ‏ ‏فِي الْمَسْجِدِ ‏ ‏فَعَقَلَهُ ‏ ‏ثُمَّ قَالَ أَيُّكُمْ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّكِئٌ بَيْنَ ‏ ‏ظَهْرَانَيْهِمْ ‏ ‏قَالَ فَقُلْنَا هَذَا الرَّجُلُ الْأَبْيَضُ الْمُتَّكِئُ فَقَالَ الرَّجُلُ يَا ‏ ‏ابْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَجَبْتُكَ فَقَالَ الرَّجُلُ إِنِّي يَا ‏ ‏مُحَمَّدُ ‏ ‏سَائِلُكَ فَمُشَدِّدٌ عَلَيْكَ فِي الْمَسْأَلَةِ فَلَا تَجِدْ عَلَيَّ فِي نَفْسِكَ فَقَالَ سَلْ مَا بَدَا لَكَ فَقَالَ الرَّجُلُ ‏ ‏نَشَدْتُكَ ‏ ‏بِرَبِّكَ وَرَبِّ مَنْ كَانَ قَبْلَكَ ‏ ‏آللَّهُ أَرْسَلَكَ إِلَى النَّاسِ كُلِّهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ نَعَمْ قَالَ ‏ ‏فَأَنْشُدُكَ ‏ ‏اللَّهَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ نُصَلِّيَ الصَّلَوَاتِ الْخَمْسَ فِي الْيَوْمِ وَاللَّيْلَةِ قَالَ اللَّهُمَّ نَعَمْ قَالَ ‏ ‏فَأَنْشُدُكَ ‏ ‏اللَّهَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ نَصُومَ هَذَا الشَّهْرَ مِنْ السَّنَةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ نَعَمْ قَالَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ تَأْخُذَ هَذِهِ ‏ ‏الصَّدَقَةَ ‏ ‏مِنْ أَغْنِيَائِنَا فَتُقَسِّمَهَا عَلَى فُقَرَائِنَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ نَعَمْ قَالَ الرَّجُلُ آمَنْتُ بِمَا جِئْتَ بِهِ وَأَنَا رَسُولُ مَنْ وَرَائِي مِنْ قَوْمِي قَالَ وَأَنَا ‏ ‏ضِمَامُ بْنُ ثَعْلَبَةَ ‏ ‏أَخُو ‏ ‏بَنِي سَعْدِ بْنِ بَكْرٍ ‏","","",""],[12259,12259,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَكْتُبَ إِلَى ‏ ‏الرُّومِ ‏ ‏قَالُوا إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا قَالَ ‏ ‏فَاتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ فِضَّةٍ كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[12260,12260,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَيَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[12261,12261,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ الْخَيْرَ خَيْرُ الْآخِرَةِ ‏ ‏أَوْ قَالَ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏هَذَا فِي قَصَصِهِ ‏","","",""],[12262,12262,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي صَدَقَةَ ‏ ‏مَوْلَى ‏ ‏أَنَسٍ ‏ ‏وَأَثْنَى عَلَيْهِ ‏ ‏شُعْبَةُ ‏ ‏خَيْرًا ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ إِذَا زَالَتْ الشَّمْسُ وَالْعَصْرَ بَيْنَ صَلَاتَيْكُمْ هَاتَيْنِ وَالْمَغْرِبَ إِذَا غَرَبَتْ الشَّمْسُ وَالْعِشَاءَ إِذَا غَابَ ‏ ‏الشَّفَقُ ‏ ‏وَالصُّبْحَ إِذَا طَلَعَ الْفَجْرُ إِلَى أَنْ يَنْفَسِحَ الْبَصَرُ ‏","","",""],[12263,12263,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى صِبْيَانٍ وَهُمْ يَلْعَبُونَ فَسَلَّمَ عَلَيْهِمْ ‏","","",""],[12264,12264,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنَاهُ عَنْ ‏ ‏هِشَامِ بْنِ زَيْدِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَسِمُ ‏ ‏غَنَمًا ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏أَحْسَبُهُ قَالَ فِي آذَانِهَا ‏ ‏قَالَ ثُمَّ قَالَ بَعْدُ فِي آذَانِهَا وَلَمْ يَشُكَّ ‏","","",""],[12265,12265,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَبْيَضِ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي عَامِرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُحَلِّقَةٌ ‏","","",""],[12266,12266,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ حَدِّثْنَا بِشَيْءٍ شَهِدْتَهُ مِنْ هَذِهِ الْأَعَاجِيبِ لَا تُحَدِّثْنَا بِهِ عَنْ غَيْرِكَ قَالَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ وَقَعَدَ عَلَى الْمَقَاعِدِ الَّتِي كَانَ يَأْتِيهِ عَلَيْهَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ فَجَاءَ ‏ ‏بِلَالٌ ‏ ‏فَآذَنَهُ بِصَلَاةِ الْعَصْرِ فَقَالَ مَنْ كَانَ لَهُ أَهْلٌ بَعِيدٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏لِيَقْضِيَ حَاجَتَهُ وَيُصِيبَ مِنْ الْوَضُوءِ وَبَقِيَ نَاسٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏لَيْسَ لَهُمْ أَهْلُونَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَدَحٍ ‏ ‏أَرْوَحَ فِي أَسْفَلِهِ شَيْءٌ مِنْ مَاءٍ قَالَ ‏ ‏فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَّهُ فِي ‏ ‏الْقَدَحِ ‏ ‏فَمَا وَسِعَتْ كَفَّهُ فَوَضَعَ أَصَابِعَهُ هَؤُلَاءِ الْأَرْبَعَ ثُمَّ قَالَ ادْنُوا فَتَوَضَّئُوا قَالَ فَتَوَضَّئُوا حَتَّى مَا بَقِيَ مِنْهُمْ أَحَدٌ إِلَّا تَوَضَّأَ ‏ ‏فَقُلْنَا ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏كَمْ ‏ ‏تُرَاهُمْ كَانُوا قَالَ ‏ ‏بَيْنَ السَّبْعِينَ إِلَى الثَّمَانِينَ ‏","","",""],[12267,12267,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ يَعْنِي ابْنَ زَاذَانَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعْجِبُهُ الْقَرْعُ ‏","","",""],[12268,12268,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ الْمُؤَذِّنُونَ ‏","","",""],[12269,12269,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا فُتِحَتْ ‏ ‏مَكَّةُ ‏ ‏قَالَ قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَنَائِمَ فِي ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏إِنَّ هَذَا لَهُوَ الْعَجَبُ إِنَّ سُيُوفَنَا ‏ ‏تَقْطُرُ ‏ ‏مِنْ دِمَائِهِمْ وَإِنَّ غَنَائِمَنَا تُرَدُّ عَلَيْهِمْ فَبَلَغَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَمَعَهُمْ فَقَالَ مَا هَذَا الَّذِي بَلَغَنِي عَنْكُمْ فَقَالُوا هُوَ الَّذِي بَلَغَكَ وَكَانُوا لَا يَكْذِبُونَ فَقَالَ ‏ ‏أَمَا تَرْضَوْنَ أَنْ يَرْجِعَ النَّاسُ بِالدُّنْيَا وَتَرْجِعُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى بُيُوتِكُمْ لَوْ سَلَكَ النَّاسُ وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏أَوْ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏","","",""],[12270,12270,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا دَعَا رَجُلًا فِي السُّوقِ فَقَالَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الرَّجُلُ إِنَّمَا عَنَيْتُ رَجُلًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمُّوا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[12271,12271,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏نَحْنُ الَّذِينَ بَايَعُوا ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْجِهَادِ مَا بَقِينَا أَبَدًا ‏ ‏فَأَجَابَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12272,12272,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَالْخُفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِ ظَهْرِي إِذَا مَا رَكَعْتُمْ وَإِذَا مَا سَجَدْتُمْ ‏","","",""],[12273,12273,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وأَسْبَاطٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[12274,12274,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏فَقَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ أَرْكَبُهَا قَالَ ارْكَبْهَا ‏","","",""],[12275,12275,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏يُذَكِّيهِمَا ‏ ‏بِيَدِهِ ‏ ‏وَيَطَأُ ‏ ‏عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏وَيَذْكُرُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[12276,12276,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏عُكْلٍ ‏ ‏أَوْ ‏ ‏عُرَيْنَةَ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا كُنَّا أَهْلَ ضَرْعٍ وَلَمْ نَكُنْ أَهْلَ رِيفٍ ‏ ‏فَاسْتَوْخَمُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَأَمَرَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَوْدٍ وَأَمَرَهُمْ أَنْ يَخْرُجُوا فِيهَا فَيَشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَاقُوا ‏ ‏الذَّوْدَ ‏ ‏وَكَفَرُوا بَعْدَ إِسْلَامِهِمْ فَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَلَبِهِمْ فَأُتِيَ بِهِمْ فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَتَرَكَهُمْ فِي ‏ ‏الْحَرَّةِ ‏ ‏حَتَّى مَاتُوا ‏","","",""],[12277,12277,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَرَادَ أَنْ يَكْتُبَ إِلَى نَاسٍ مِنْ هَذِهِ ‏ ‏الْأَعَاجِمِ ‏ ‏قِيلَ لَهُ إِنَّهُمْ لَا يَقْبَلُونَ كِتَابًا إِلَّا بِخَاتَمٍ قَالَ ‏ ‏فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ نَقْشُهُ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏وَنَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى بَصِيصِهِ ‏ ‏أَوْ بَيَاضِهِ ‏ ‏فِي يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12278,12278,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزَيْدَ بْنَ ثَابِتٍ ‏ ‏تَسَحَّرَا فَلَمَّا فَرَغَا مِنْ سُحُورِهِمَا قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الصَّلَاةِ فَصَلَّى ‏ ‏فَقُلْنَا ‏ ‏لِأَنَسٍ ‏ ‏كَمْ كَانَ بَيْنَ فَرَاغِهِمَا وَسُحُورِهِمَا وَدُخُولِهِمَا فِي الصَّلَاةِ قَالَ ‏ ‏كَانَ قَدْرَ مَا يَقْرَأُ رَجُلٌ خَمْسِينَ آيَةً ‏","","",""],[12279,12279,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏تُوَاصِلُوا ‏ ‏فَقِيلَ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ إِنَّ رَبِّي يُطْعِمُنِي وَيَسْقِينِي ‏","","",""],[12280,12280,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ يَهُودِيًّا قَتَلَ ‏ ‏جَارِيَةً ‏ ‏عَلَى ‏ ‏أَوْضَاحٍ ‏ ‏لَهَا ‏ ‏فَقَتَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12281,12281,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏بِالزَّوْرَاءِ ‏ ‏فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ لَا يَغْمُرُ أَصَابِعَهُ فَأَمَرَ أَصْحَابَهُ أَنْ يَتَوَضَّئُوا ‏ ‏فَوَضَعَ كَفَّهُ فِي الْمَاءِ فَجَعَلَ الْمَاءُ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ وَأَطْرَافِ أَصَابِعِهِ حَتَّى تَوَضَّأَ الْقَوْمُ ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَمْ كُنْتُمْ ‏ ‏قَالَ ‏ ‏كُنَّا ثَلَاثَ مِائَةٍ ‏","","",""],[12282,12282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[12283,12283,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ فَزَعٌ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَاسْتَعَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا لَنَا يُقَالُ لَهُ مَنْدُوبٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَيْنَا مِنْ فَزَعٍ وَإِنْ وَجَدْنَاهُ لَبَحْرًا ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَعْنِي الْفَرَسَ ‏","","",""],[12284,12284,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي قَزَعَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ وَكَانَتْ رُكْبَةُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏تَكَادُ أَنْ تُصِيبَ رُكْبَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏بِهِمَا ‏","","",""],[12285,12285,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِشَامَ بْنَ زَيْدِ بْنِ أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ جَدِّي ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏دَارَ ‏ ‏الْحَكَمِ بْنِ أَيُّوبَ ‏ ‏فَإِذَا قَوْمٌ قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا فَقَالَ ‏ ‏أَنَسٌ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُصْبَرَ ‏ ‏الْبَهَائِمُ ‏","","",""],[12286,12286,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَرَرْنَا ‏ ‏فَأَنْفَجْنَا ‏ ‏أَرْنَبًا ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏فَسَعَوْا عَلَيْهَا ‏ ‏فَلَغَبُوا ‏ ‏فَسَعَيْتُ حَتَّى أَدْرَكْتُهَا فَأَتَيْتُ بِهَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏فَذَبَحَهَا فَبَعَثَ بِوَرِكِهَا ‏ ‏أَوْ فَخِذِهَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبِلَهُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قُلْتُ ‏ ‏لِشُعْبَةَ ‏ ‏فَقُلْتُ ‏ ‏أَكَلَهُ ‏ ‏قَالَ ‏ ‏نَعَمْ أَكَلَهُ قَالَ لِي بَعْدُ قَبِلَهُ ‏","","",""],[12287,12287,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ يَهُودِيًّا قَتَلَ ‏ ‏جَارِيَةً ‏ ‏عَلَى ‏ ‏أَوْضَاحٍ ‏ ‏لَهَا قَالَ فَقَتَلَهَا بِحَجَرٍ قَالَ فَجِيءَ بِهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِهَا ‏ ‏رَمَقٌ ‏ ‏فَقَالَ لَهَا ‏ ‏قَتَلَكِ فُلَانٌ فَأَشَارَتْ بِرَأْسِهَا أَيْ لَا ثُمَّ قَالَ لَهَا الثَّانِيَةَ فَأَشَارَتْ بِرَأْسِهَا أَيْ لَا ثُمَّ سَأَلَهَا الثَّالِثَةَ فَقَالَتْ نَعَمْ وَأَشَارَتْ بِرَأْسِهَا فَقَتَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ حَجَرَيْنِ ‏","","",""],[12288,12288,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْأَنْصَارِ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي فَمَوْعِدُكُمْ الْحَوْضُ ‏","","",""],[12289,12289,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ أُمَّهُ حِينَ وَلَدَتْ انْطَلَقُوا بِالصَّبِيِّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُحَنِّكَهُ ‏ ‏قَالَ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏مِرْبَدٍ ‏ ‏يَسِمُ ‏ ‏غَنَمًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْبَرُ عِلْمِي أَنَّهُ قَالَ فِي آذَانِهَا ‏","","",""],[12290,12290,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا التَّيَّاحِ يَزِيدَ بْنَ حُمَيْدٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَرَكَةُ فِي ‏ ‏نَوَاصِي ‏ ‏الْخَيْلِ ‏","","",""],[12291,12291,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأَبِي ذَرٍّ ‏ ‏اسْمَعْ وَأَطِعْ وَلَوْ لِحَبَشِيٍّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ ‏","","",""],[12292,12292,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَالِطُنَا حَتَّى إِنْ كَانَ لَيَقُولُ لِأَخٍ لِي يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏ ‏قَالَ وَكَانَ إِذَا حَضَرَتْ الصَّلَاةُ ‏ ‏نَضَحْنَا ‏ ‏لَهُ طَرَفَ بِسَاطٍ ثُمَّ أَمَّنَا وَصَفَّنَا خَلْفَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ إِنَّ ‏ ‏أَبَا التَّيَّاحِ ‏ ‏بَعْدَمَا كَبِرَ قَالَ ثُمَّ قَامَ فَصَلَّى وَلَمْ يَقُلْ صَفَّنَا خَلْفَهُ وَلَا أَمَّنَا ‏","","",""],[12293,12293,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ ‏ ‏الْخَلَاءَ ‏ ‏فَأَحْمِلُ أَنَا وَغُلَامٌ نَحْوِي ‏ ‏إِدَاوَةً ‏ ‏مِنْ مَاءٍ ‏ ‏وَعَنَزَةً ‏ ‏فَيَسْتَنْجِي ‏ ‏بِالْمَاءِ ‏","","",""],[12294,12294,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَا يَتَمَنَّى الْمُؤْمِنُ ‏ ‏أَوْ قَالَ أَحَدُكُمْ ‏ ‏الْمَوْتَ فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ ‏ ‏اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي مَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[12295,12295,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏","","",""],[12296,12296,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ ‏ ‏الْآخِرَهْ قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ ‏ ‏اللَّهُمَّ إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَأَصْلِحْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12297,12297,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ رُئِيَ ‏ ‏أَوْ رَأَيْتُ ‏ ‏بَيَاضَ إِبِطَيْهِ ‏","","",""],[12298,12298,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا أَوْلَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى امْرَأَةٍ مِنْ نِسَائِهِ أَكْثَرَ ‏ ‏أَوْ أَفْضَلَ ‏ ‏مِمَّا أَوْلَمَ عَلَى ‏ ‏زَيْنَبَ ‏ ‏فَقَالَ ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏فَمَا أَوْلَمَ ‏ ‏قَالَ ‏ ‏أَطْعَمَهُمْ خُبْزًا وَلَحْمًا حَتَّى تَرَكُوهُ ‏","","",""],[12299,12299,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يَنْعَتُ ‏ ‏لَنَا صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏يَقُومُ فَيُصَلِّي فَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قُلْنَا قَدْ نَسِيَ مِنْ طُولِ مَا يَقُومُ ‏","","",""],[12300,12300,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسِيرُ ‏ ‏وَحَادٍ ‏ ‏يَحْدُو ‏ ‏بِنِسَائِهِ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ قَدْ ‏ ‏تَنَحَّى ‏ ‏بِهِنَّ قَالَ فَقَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏وَيْحَكَ ‏ ‏ارْفُقْ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[12301,12301,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَتَى السَّاعَةُ فَقَالَ مَا أَعْدَدْتَ لَهَا فَقَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ صَلَاةٍ وَلَا صَوْمٍ وَلَا ‏ ‏صَدَقَةٍ ‏ ‏إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12302,12302,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَتَّابًا ‏ ‏مَوْلَى ‏ ‏ابْنِ هُرْمُزَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي هَذِهِ ‏ ‏يَعْنِي الْيُمْنَى ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فِيمَا اسْتَطَعْتُ ‏","","",""],[12303,12303,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَتَّابٍ ‏ ‏وَقَالَ ‏ ‏هَاشِمٌ ‏ ‏مَوْلَى ‏ ‏بَنِي هُرْمُزَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنْ أَخْشَى أَنْ أُخْطِئَ لَحَدَّثْتُكُمْ بِأَشْيَاءَ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَكِنَّهُ قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏قَالَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12304,12304,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ طَعْمَ الْإِيمَانِ مَنْ كَانَ يُحِبُّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَمَنْ كَانَ اللَّهُ تَبَارَكَ وَتَعَالَى وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَمَنْ كَانَ أَنْ يُلْقَى فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ ‏","","",""],[12305,12305,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ أَفِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ‏ ‏ابْنَ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوْ مِنْ أَنْفُسِهِمْ ‏ ‏فَقَالَ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ وَمُصِيبَةٍ وَإِنِّي أَرَدْتُ أَنْ أَجْبُرَهُمْ ‏ ‏وَأَتَأَلَّفَهُمْ ‏ ‏أَمَا تَرْضَوْنَ أَنْ يَرْجِعَ النَّاسُ بِالدُّنْيَا وَتَرْجِعُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى بُيُوتِكُمْ لَوْ سَلَكَ النَّاسُ وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَأَرَدْتُ أَنْ أَتَأَلَّفَهُمْ وَأَجْبُرَهُمْ ‏","","",""],[12306,12306,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَأَكْرِمْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12307,12307,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَتَى السَّاعَةُ قَالَ مَا أَعْدَدْتَ لَهَا قَالَ حُبَّ اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ قَالَ أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[12308,12308,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَبِيٍّ إِلَّا وَقَدْ أَنْذَرَ أُمَّتَهُ الْأَعْوَرَ الْكَذَّابَ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَفَرَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏كَافِرٌ ‏","","",""],[12309,12309,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ غَيْرَ الشَّهِيدِ فَإِنَّهُ يَتَمَنَّى أَنْ يَرْجِعَ فَيُقْتَلَ عَشْرَ مَرَّاتٍ لِمَا يَرَى مِنْ الْكَرَامَةِ ‏","","",""],[12310,12310,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ مَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ مَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ مَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ‏ ‏بُرَّةً ‏","","",""],[12311,12311,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَا أَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[12312,12312,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَأَسْوَدُ يَعْنِي شَاذَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا ‏ ‏وَيْحَكَ ‏ ‏فِي الثَّالِثَةِ ‏","","",""],[12313,12313,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ قَالَ قُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏أَسَمِعْتَ ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏الْبُصَاقُ فِي الْمَسْجِدِ خَطِيئَةٌ قَالَ نَعَمْ وَكَفَّارَتُهُ دَفْنُهُ ‏","","",""],[12314,12314,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ لَسْتُمْ فِي ذَلِكَ مِثْلِي إِنِّي أَظَلُّ ‏ ‏أَوْ قَالَ أَبِيتُ ‏ ‏أُطْعَمُ وَأُسْقَى ‏","","",""],[12315,12315,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ جَمَعَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ هَلْ فِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ‏ ‏ابْنَ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْ أَنْفُسِهِمْ ‏ ‏أَوْ قَالَ مِنْ الْقَوْمِ ‏ ‏قَالَ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِمُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏أَنَسٍ ‏","","",""],[12316,12316,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏قَالَ وَيُعْجِبُنِي الْفَأْلُ فَقُلْتُ مَا الْفَأْلُ قَالَ الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[12317,12317,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏} ‏ثُمَّ يَقُولُ قَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَنِيئًا ‏ ‏مَرِيئًا ‏ ‏لَكَ يَا رَسُولَ اللَّهِ فَمَا لَنَا فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ ‏ ‏تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّئَاتِهِمْ ‏} ‏و قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَانَ ‏ ‏قَتَادَةُ ‏ ‏يَذْكُرُ هَذَا الْحَدِيثَ فِي قَصَصِهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ لَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ ‏} ‏ثُمَّ يَقُولُ قَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَنِيئًا لَكَ هَذَا الْحَدِيثُ ‏ ‏قَالَ ‏ ‏فَظَنَنْتُ أَنَّهُ كُلُّهُ عَنْ ‏ ‏أَنَسٍ ‏ ‏فَأَتَيْتُ ‏ ‏الْكُوفَةَ ‏ ‏فَحَدَّثْتُ عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏ثُمَّ رَجَعْتُ فَلَقِيتُ ‏ ‏قَتَادَةَ ‏ ‏بِوَاسِطٍ ‏ ‏فَإِذَا هُوَ يَقُولُ أَوَّلُهُ عَنْ ‏ ‏أَنَسٍ ‏ ‏وَآخِرُهُ عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ فَأَتَيْتُهُمْ ‏ ‏بِالْكُوفَةِ ‏ ‏فَأَخْبَرْتُهُمْ بِذَلِكَ ‏","","",""],[12318,12318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏إِنْ كَانَتْ الْوَلِيدَةُ مِنْ وَلَائِدِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏لَتَجِيءُ فَتَأْخُذُ بِيَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا يَنْزِعُ يَدَهُ مِنْ يَدِهَا حَتَّى تَذْهَبَ بِهِ حَيْثُ شَاءَتْ ‏","","",""],[12319,12319,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ يَعْنِي الْأَنْصَارِيَّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏} ‏أَوْ قَالَ ‏ { ‏مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا ‏} ‏قَالَ جَاءَ ‏ ‏أَبُو طَلْحَةَ بْنُ سَهْلٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏حَائِطِي ‏ ‏الَّذِي بِمَكَانِ كَذَا وَكَذَا وَلَوْ اسْتَطَعْتُ يَا رَسُولَ اللَّهِ أَنْ أُسِرَّهُ لَمْ أُعْلِنْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلْهُ فِي فُقَرَاءِ قَرَابَتِكَ ‏ ‏أَوْ قَالَ فِي ‏ ‏فُقَرَاءِ أَهْلِكَ ‏","","",""],[12320,12320,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِلَالَ بْنَ أَبِي دَاوُدَ الْحَبَطِيَّ أَبَا هِشَامٍ ‏ ‏قَالَ ‏ ‏أَخِي ‏ ‏هَارُونُ بْنُ أَبِي دَاوُدَ ‏ ‏حَدَّثَنِي قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏إِنَّ الْمَكَانَ بَعِيدٌ وَنَحْنُ يُعْجِبُنَا أَنْ نَعُودَكَ فَرَفَعَ رَأْسَهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا رَجُلٍ يَعُودُ مَرِيضًا فَإِنَّمَا يَخُوضُ فِي الرَّحْمَةِ فَإِذَا قَعَدَ عِنْدَ الْمَرِيضِ غَمَرَتْهُ الرَّحْمَةُ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا لِلصَّحِيحِ الَّذِي يَعُودُ الْمَرِيضَ فَالْمَرِيضُ مَا لَهُ قَالَ تُحَطُّ عَنْهُ ذُنُوبُهُ ‏","","",""],[12321,12321,"","","‏ ‏حَدَّثَنَا ‏ ‏الْمُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلَاوَةَ الْإِيمَانِ أَنْ يَكُونَ اللَّهُ عَزَّ وَجَلَّ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَأَنْ يَكْرَهَ الْعَبْدُ أَنْ يَرْجِعَ عَنْ الْإِسْلَامِ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ وَأَنْ يُحِبَّ الْعَبْدُ الْعَبْدَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[12322,12322,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَأَنَا ابْنُ تِسْعِ سِنِينَ فَانْطَلَقَتْ بِي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ هَذَا ابْنِي اسْتَخْدِمْهُ فَخَدَمْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَ سِنِينَ فَمَا قَالَ لِي لِشَيْءٍ فَعَلْتُهُ لِمَ فَعَلْتَ كَذَا وَكَذَا وَمَا قَالَ لِي لِشَيْءٍ لَمْ أَفْعَلْهُ أَلَا فَعَلْتَ كَذَا وَكَذَا وَأَتَانِي ذَاتَ يَوْمٍ وَأَنَا أَلْعَبُ مَعَ الْغِلْمَانِ ‏ ‏أَوْ قَالَ مَعَ الصِّبْيَانِ ‏ ‏فَسَلَّمَ عَلَيْنَا وَدَعَانِي فَأَرْسَلَنِي فِي حَاجَةٍ فَلَمَّا رَجَعْتُ قَالَ ‏ ‏لَا تُخْبِرْ أَحَدًا وَاحْتَبَسْتُ عَلَى أُمِّي فَلَمَّا أَتَيْتُهَا قَالَتْ يَا بُنَيَّ مَا حَبَسَكَ قُلْتُ أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ قَالَتْ وَمَا هِيَ قُلْتُ إِنَّهُ قَالَ لَا تُخْبِرْ بِهَا أَحَدًا قَالَتْ أَيْ بُنَيَّ فَاكْتُمْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرَّهُ ‏","","",""],[12323,12323,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَيْبَةَ ‏ ‏حَجَمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ لَهُ ‏ ‏بِصَاعٍ ‏ ‏مِنْ تَمْرٍ وَكَلَّمَ أَهْلَهُ فَوَضَعُوا عَنْهُ مِنْ خَرَاجِهِ ‏","","",""],[12324,12324,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِأَصْحَابِهِ ‏ ‏سَلُونِي فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏لِلَّذِي كَانَ يُنْسَبُ إِلَيْهِ فَقَالَتْ لَهُ أُمُّهُ يَا بُنَيَّ لَقَدْ قُمْتَ بِأُمِّكَ مَقَامًا عَظِيمًا قَالَ أَرَدْتُ أَنْ أُبَرِّئَ صَدْرِي مِمَّا كَانَ يُقَالُ وَقَدْ كَانَ يُقَالُ فِيهِ ‏","","",""],[12325,12325,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الْقَرْعُ فَكَانَ إِذَا جِيءَ بِمَرَقَةٍ فِيهَا قَرْعٌ جُعِلَتْ الْقَرْعُ مِمَّا يَلِيهِ ‏","","",""],[12326,12326,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ ‏ ‏ذَهَبَ بَصَرُهُ فَقَالَ يَا رَسُولَ اللَّهِ لَوْ جِئْتَ صَلَّيْتَ فِي دَارِي ‏ ‏أَوْ قَالَ فِي بَيْتِي ‏ ‏لَاتَّخَذْتُ مُصَلَّاكَ مَسْجِدًا فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فِي دَارِهِ ‏ ‏أَوْ قَالَ فِي بَيْتِهِ ‏ ‏وَاجْتَمَعَ قَوْمُ ‏ ‏عِتْبَانَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَذَكَرُوا ‏ ‏مَالِكَ بْنَ الدُّخْشُمِ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهُ وَإِنَّهُ ‏ ‏يُعَرِّضُونَ ‏ ‏بِالنِّفَاقِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ قَالُوا بَلَى قَالَ وَالَّذِي نَفْسِي ‏ ‏بِيَدِهِ لَا يَقُولُهَا عَبْدٌ صَادِقٌ بِهَا إِلَّا حُرِّمَتْ عَلَيْهِ النَّارُ ‏","","",""],[12327,12327,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ وَفْدًا مِنْ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏قَدِمُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرَادَ أَنْ يَبْعَثَ مَعَهُمْ رَجُلًا فَقَالُوا ابْعَثْ مَعَنَا رَجُلًا فَقَالَ ‏ ‏أَبْعَثُ مَعَكُمْ أَمِينَ هَذِهِ الْأُمَّةِ فَبَعَثَ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَفِي مَوْضِعٍ آخَرَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ابْعَثْ مَعَنَا رَجُلًا يُعَلِّمُنَا فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏فَقَالَ لِكُلِّ أُمَّةٍ أَمِينٌ وَهَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏","","",""],[12328,12328,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ ‏ ‏فَأَعْطَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا بَيْنَ جَبَلَيْنِ فَأَتَى الرَّجُلُ قَوْمَهُ فَقَالَ أَيْ قَوْمِي أَسْلِمُوا فَوَاللَّهِ إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏لَيُعْطِي عَطِيَّةَ رَجُلٍ مَا يَخَافُ ‏ ‏الْفَاقَةَ ‏ ‏أَوْ قَالَ الْفَقْرَ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏ثَابِتٌ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسٌ ‏ ‏إِنْ كَانَ الرَّجُلُ لَيَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْلِمُ مَا يُرِيدُ إِلَّا أَنْ يُصِيبَ ‏ ‏عَرَضًا ‏ ‏مِنْ الدُّنْيَا ‏ ‏أَوْ قَالَ دُنْيَا يُصِيبُهَا ‏ ‏فَمَا يُمْسِي مِنْ يَوْمِهِ ذَلِكَ حَتَّى يَكُونَ دِينُهُ أَحَبَّ إِلَيْهِ ‏ ‏أَوْ قَالَ أَكْبَرَ عَلَيْهِ ‏ ‏مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[12329,12329,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏وَحَسَنٌ الْأَشْيَبُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَحُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى بَغْلَتِهِ الشَّهْبَاءِ ‏ ‏بِحَائِطٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فَسَمِعَ أَصْوَاتَ قَوْمٍ يُعَذَّبُونَ فِي قُبُورِهِمْ فَحَاصَتْ الْبَغْلَةُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَسَأَلْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[12330,12330,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ غُلَامًا يَهُودِيًّا كَانَ يَضَعُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءَهُ وَيُنَاوِلُهُ نَعْلَيْهِ فَمَرِضَ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ عَلَيْهِ وَأَبُوهُ قَاعِدٌ عِنْدَ رَأْسِهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ ‏ ‏قُلْ لَا إِلَهَ إِلَّا اللَّهُ فَنَظَرَ إِلَى أَبِيهِ فَسَكَتَ أَبُوهُ فَأَعَادَ عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى أَبِيهِ فَقَالَ أَبُوهُ أَطِعْ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَقَالَ الْغُلَامُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ الْحَمْدُ لِلَّهِ الَّذِي أَخْرَجَهُ بِي مِنْ النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏مِثْلَهُ ‏","","",""],[12331,12331,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَضَرَتْ الصَّلَاةُ فَقَامَ جِيرَانُ الْمَسْجِدِ إِلَى مَنَازِلِهِمْ يَتَوَضَّئُونَ وَبَقِيَ فِي الْمَسْجِدِ نَاسٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مَا بَيْنَ السَّبْعِينَ إِلَى الثَّمَانِينَ فَدَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَاءٍ فَأُتِيَ ‏ ‏بِمِخْضَبٍ ‏ ‏مِنْ حِجَارَةٍ فِيهِ مَاءٌ ‏ ‏فَوَضَعَ أَصَابِعَ يَدِهِ الْيُمْنَى فِي ‏ ‏الْمِخْضَبِ ‏ ‏فَجَعَلَ يَصُبُّ عَلَيْهِمْ وَهُمْ يَتَوَضَّئُونَ وَيَقُولُ تَوَضَّئُوا حَيَّ عَلَى الْوُضُوءِ حَتَّى تَوَضَّئُوا جَمِيعًا وَبَقِيَ فِيهِ نَحْوٌ مِمَّا كَانَ فِيهِ ‏","","",""],[12332,12332,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ ‏ ‏بِعَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وُلِدَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي عَبَاءَةٍ يَهْنَأُ بَعِيرًا لَهُ فَقَالَ لِي ‏ ‏أَمَعَكَ تَمْرٌ قُلْتُ نَعَمْ فَتَنَاوَلَ تَمَرَاتٍ فَأَلْقَاهُنَّ فِي ‏ ‏فِيهِ ‏ ‏فَلَاكَهُنَّ ‏ ‏فِي ‏ ‏حَنَكِهِ ‏ ‏فَفَغَرَ ‏ ‏الصَّبِيُّ ‏ ‏فَاهُ ‏ ‏فَأَوْجَرَهُ ‏ ‏فَجَعَلَ الصَّبِيُّ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَتْ ‏ ‏الْأَنْصَارُ ‏ ‏إِلَّا حُبَّ التَّمْرِ وَسَمَّاهُ ‏ ‏عَبْدَ اللَّهِ ‏","","",""],[12333,12333,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا إِذَا كُنَّا عِنْدَكَ فَحَدَّثْتَنَا رَقَّتْ قُلُوبُنَا فَإِذَا خَرَجْنَا مِنْ عِنْدِكَ عَافَسْنَا النِّسَاءَ وَالصِّبْيَانَ وَفَعَلْنَا وَفَعَلْنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ تِلْكَ السَّاعَةَ لَوْ تَدُومُونَ عَلَيْهَا لَصَافَحَتْكُمْ الْمَلَائِكَةُ ‏","","",""],[12334,12334,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ إِبْرَاهِيمَ ابْنِ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى الصِّبْيَانَ وَالنِّسَاءَ مُقْبِلِينَ ‏ ‏قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ مِنْ ‏ ‏عُرْسٍ ‏ ‏فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُمْثِلًا فَقَالَ ‏ ‏اللَّهُمَّ أَنْتُمْ مِنْ أَحَبِّ النَّاسِ إِلَيَّ اللَّهُمَّ أَنْتُمْ مِنْ أَحَبِّ النَّاسِ إِلَيَّ اللَّهُمَّ أَنْتُمْ مِنْ أَحَبِّ النَّاسِ إِلَيَّ ‏ ‏يَعْنِي ‏ ‏الْأَنْصَارَ ‏","","",""],[12335,12335,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏قَالَ ‏ ‏عَطَسَ رَجُلَانِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَمَّتَ ‏ ‏أَحَدَهُمَا ‏ ‏أَوْ قَالَ ‏ ‏سَمَّتَ ‏ ‏أَحَدَهُمَا ‏ ‏وَتَرَكَ الْآخَرَ فَقِيلَ هُمَا رَجُلَانِ عَطَسَا ‏ ‏فَشَمَّتَّ ‏ ‏أَوْ قَالَ فَسَمَّتَّ ‏ ‏أَحَدَهُمَا وَتَرَكْتَ الْآخَرَ فَقَالَ إِنَّ هَذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ وَإِنَّ هَذَا لَمْ يَحْمَدْ اللَّهَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏أُرَاهُ نَحْوًا مِنْ هَذَا ‏","","",""],[12336,12336,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏مَعَ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَسُوقُ بِهِنَّ سَوَّاقٌ فَقَالَ لَهُ يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[12337,12337,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏ ‏هَكَذَا مَرَّتَيْنِ وَثَنَا بِهِ مَرَّةً أُخْرَى فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[12338,12338,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ ‏ ‏أَوْ لِجَارِهِ ‏ ‏مَا يُحِبُّ لِنَفْسِهِ ‏ ‏وَلَمْ يَشُكَّ ‏ ‏حَجَّاجٌ ‏","","",""],[12339,12339,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْأَنْصَارَ ‏ ‏كَرِشِي ‏ ‏وَعَيْبَتِي ‏ ‏وَإِنَّ النَّاسَ سَيَكْثُرُونَ وَيَقِلُّونَ فَاقْبَلُوا مِنْ مُحْسِنِهِمْ وَاعْفُوا عَنْ مُسِيئِهِمْ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏مُسِيِّهِمْ ‏","","",""],[12340,12340,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَلَا أَدْرِي أَشَيْءٌ أُنْزِلَ أَوْ كَانَ يَقُولُهُ لَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَيْنِ مِنْ مَالٍ لَتَمَنَّى أَوْ لَابْتَغَى وَادِيًا ثَالِثًا ‏ ‏وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَلَا أَدْرِي أَشَيْءٌ أُنْزِلَ عَلَيْهِ فَذَكَرَهُ ‏","","",""],[12341,12341,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ قَدْ شَرِبَ الْخَمْرَ فَجَلَدَهُ بِجَرِيدَتَيْنِ نَحْوَ الْأَرْبَعِينَ ‏ ‏قَالَ ‏ ‏وَفَعَلَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَلَمَّا كَانَ ‏ ‏عُمَرُ ‏ ‏اسْتَشَارَ النَّاسَ فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏أَخَفُّ ‏ ‏الْحُدُودِ ‏ ‏ثَمَانُونَ قَالَ فَأَمَرَ بِهِ ‏ ‏عُمَرُ ‏","","",""],[12342,12342,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي سَمِعَهُ مِنْهُ ‏ ‏إِنَّ مِنْ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ أَنْ يُرْفَعَ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ ‏ ‏وَيَفْشُوَ ‏ ‏الزِّنَا وَيُشْرَبَ الْخَمْرُ وَيَذْهَبَ الرِّجَالُ ‏ ‏وَيَبْقَى النِّسَاءُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏قَيِّمٌ ‏ ‏وَاحِدٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَأُحَدِّثَنَّكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ يَذْهَبُ الرِّجَالُ وَيَبْقَى النِّسَاءُ ‏","","",""],[12343,12343,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[12344,12344,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاةٍ فَإِنَّهُ يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ فَلَا يَبْزُقَنَّ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَبْصُقَنَّ ‏ ‏بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ شِمَالِهِ وَتَحْتَ قَدَمِهِ ‏","","",""],[12345,12345,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقْرَأُ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏بِأَيِّ شَيْءٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَفْتِحُ الْقِرَاءَةَ فَقَالَ ‏ ‏إِنَّكَ لَتَسْأَلُنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ ‏","","",""],[12346,12346,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ ‏ ‏الدُّبَّاءَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏الْقَرْعَ ‏ ‏قَالَ فَأُتِيَ بِطَعَامٍ ‏ ‏أَوْ دُعِيَ لَهُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَجَعَلْتُ أَتَتَبَّعُهُ فَأَضَعُهُ بَيْنَ يَدَيْهِ لِمَا أَعْلَمُ أَنَّهُ يُحِبُّهُ ‏","","",""],[12347,12347,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الْكَلْبِ ‏","","",""],[12348,12348,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ تَمَامِ الصَّلَاةِ ‏","","",""],[12349,12349,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[12350,12350,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْعَقُ أَصَابِعَهُ الثَّلَاثَ إِذَا أَكَلَ وَقَالَ ‏ ‏إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏عَنْهَا الْأَذَى وَلْيَأْكُلْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ ‏ ‏وَلْيَسْلُتْ ‏ ‏أَحَدُكُمْ الصَّحْفَةَ فَإِنَّكُمْ لَا تَدْرُونَ فِي أَيِّ طَعَامِكُمْ الْبَرَكَةَ ‏","","",""],[12351,12351,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَجِمُ ‏ ‏وَلَمْ يَكُنْ يَظْلِمُ أَحَدًا أَجْرَهُ ‏","","",""],[12352,12352,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ يَعْنِي ابْنَ عَدِيٍّ ‏ ‏قَالَ ‏ ‏شَكَوْنَا إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏مَا نَلْقَى مِنْ ‏ ‏الْحَجَّاجِ ‏ ‏فَقَالَ ‏ ‏اصْبِرُوا فَإِنَّهُ لَا يَأْتِي عَلَيْكُمْ عَامٌ ‏ ‏أَوْ يَوْمٌ ‏ ‏إِلَّا الَّذِي بَعْدَهُ شَرٌّ مِنْهُ حَتَّى تَلْقَوْا رَبَّكُمْ عَزَّ وَجَلَّ سَمِعْتُهُ مِنْ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12353,12353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏وَإِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا وَصَلَّى الْعَصْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[12354,12354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ سَنْبَرٌ الْجَحْدَرِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَاسًا أَتَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَأَمَرَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِبِلٍ وَرَاعِيهَا وَأَمَرَهُمْ أَنْ يَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا قَالَ فَقَتَلُوا ‏ ‏الرَّاعِيَ ‏ ‏وَأَطْرَدُوا الْإِبِلَ فَبَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَلَبِهِمْ فَجِيءَ بِهِمْ فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَلَ ‏ ‏أَعْيُنَهُمْ وَطَرَحَهُمْ فِي الشَّمْسِ حَتَّى مَاتُوا ‏","","",""],[12355,12355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ النَّاسُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏أَحْفَوْهُ ‏ ‏بِالْمَسْأَلَةِ فَصَعِدَ الْمِنْبَرَ ذَاتَ يَوْمٍ فَقَالَ لَا تَسْأَلُونِي عَنْ شَيْءٍ إِلَّا بَيَّنْتُهُ لَكُمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَجَعَلْتُ أَنْظُرُ يَمِينًا وَشِمَالًا فَإِذَا كُلُّ إِنْسَانٍ لَاوٍ رَأْسَهُ فِي ثَوْبِهِ يَبْكِي قَالَ ‏ ‏وَأَنْشَأَ ‏ ‏رَجُلٌ كَانَ إِذَا ‏ ‏لَاحَى ‏ ‏يُدْعَى إِلَى غَيْرِ أَبِيهِ فَقَالَ يَا رَسُولَ اللَّهِ مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏وَأَحْسَبُهُ قَالَ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ فِي الْجَنَّةِ أَوْ فِي النَّارِ قَالَ فِي النَّارِ قَالَ ثُمَّ ‏ ‏أَنْشَأَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏نَبِيًّا نَعُوذُ بِاللَّهِ مِنْ شَرِّ الْفِتَنِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَيْتُ فِي الْخَيْرِ وَالشَّرِّ كَالْيَوْمِ قَطُّ إِنَّهُ صُوِّرَتْ الْجَنَّةُ وَالنَّارُ حَتَّى رَأَيْتُهُمَا دُونَ الْحَائِطِ ‏","","",""],[12356,12356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِ ظَهْرِي إِذَا مَا رَكَعْتُمْ وَإِذَا مَا سَجَدْتُمْ ‏","","",""],[12357,12357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَيُعْجِبُنِي الْفَأْلُ قَالَ قِيلَ يَا نَبِيَّ اللَّهِ مَا الْفَأْلُ قَالَ الْكَلِمَةُ الْحَسَنَةُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏أَوْ قَالَ الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[12358,12358,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏أَوْ ‏ ‏أَعْرَابِيٌّ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَتَى السَّاعَةُ قَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا رَأَيْتُ الْمُسْلِمِينَ فَرِحُوا بِشَيْءٍ بَعْدَ الْإِسْلَامِ أَشَدَّ مَا فَرِحُوا يَوْمَئِذٍ ‏","","",""],[12359,12359,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ مَيْمُونٍ أَبُو الْخَطَّابِ الْأَنْصَارِيُّ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَقَائِمٌ أَنْتَظِرُ أُمَّتِي تَعْبُرُ عَلَى الصِّرَاطِ إِذْ جَاءَنِي ‏ ‏عِيسَى ‏ ‏فَقَالَ هَذِهِ الْأَنْبِيَاءُ قَدْ جَاءَتْكَ يَا ‏ ‏مُحَمَّدُ ‏ ‏يَسْأَلُونَ ‏ ‏أَوْ قَالَ يَجْتَمِعُونَ إِلَيْكَ ‏ ‏وَيَدْعُونَ اللَّهَ عَزَّ وَجَلَّ أَنْ يُفَرِّقَ جَمْعَ الْأُمَمِ إِلَى حَيْثُ يَشَاءُ اللَّهُ لِغَمِّ مَا هُمْ فِيهِ وَالْخَلْقُ ‏ ‏مُلْجَمُونَ ‏ ‏فِي الْعَرَقِ وَأَمَّا الْمُؤْمِنُ فَهُوَ عَلَيْهِ ‏ ‏كَالزَّكْمَةِ ‏ ‏وَأَمَّا الْكَافِرُ ‏ ‏فَيَتَغَشَّاهُ الْمَوْتُ قَالَ قَالَ ‏ ‏لِعِيسَى ‏ ‏انْتَظِرْ حَتَّى أَرْجِعَ إِلَيْكَ قَالَ فَذَهَبَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قَامَ تَحْتَ الْعَرْشِ فَلَقِيَ مَا لَمْ يَلْقَ مَلَكٌ مُصْطَفًى وَلَا نَبِيٌّ مُرْسَلٌ ‏ ‏فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَى ‏ ‏جِبْرِيلَ ‏ ‏اذْهَبْ إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏فَقُلْ لَهُ ارْفَعْ رَأْسَكَ سَلْ تُعْطَ ‏ ‏وَاشْفَعْ ‏ ‏تُشَفَّعْ ‏ ‏قَالَ ‏ ‏فَشُفِّعْتُ ‏ ‏فِي أُمَّتِي أَنْ أُخْرِجَ مِنْ كُلِّ تِسْعَةٍ وَتِسْعِينَ إِنْسَانًا وَاحِدًا قَالَ فَمَا زِلْتُ أَتَرَدَّدُ عَلَى رَبِّي عَزَّ وَجَلَّ فَلَا أَقُومُ مَقَامًا إِلَّا ‏ ‏شُفِّعْتُ ‏ ‏حَتَّى أَعْطَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ ذَلِكَ أَنْ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَدْخِلْ مِنْ أُمَّتِكَ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ مَنْ شَهِدَ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ يَوْمًا وَاحِدًا مُخْلِصًا وَمَاتَ عَلَى ذَلِكَ ‏","","",""],[12360,12360,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ مَيْمُونٍ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَشْفَعَ لِي يَوْمَ الْقِيَامَةِ قَالَ قَالَ أَنَا فَاعِلٌ بِهِمْ قَالَ فَأَيْنَ أَطْلُبُكَ يَوْمَ الْقِيَامَةِ يَا نَبِيَّ اللَّهِ قَالَ اطْلُبْنِي أَوَّلَ مَا تَطْلُبُنِي عَلَى الصِّرَاطِ قَالَ قُلْتُ فَإِذَا لَمْ أَلْقَكَ عَلَى الصِّرَاطِ قَالَ فَأَنَا عِنْدَ الْمِيزَانِ قَالَ قُلْتُ فَإِنْ لَمْ أَلْقَكَ عِنْدَ الْمِيزَانِ قَالَ فَأَنَا عِنْدَ الْحَوْضِ لَا أُخْطِئُ هَذِهِ الثَّلَاثَ مَوَاطِنَ يَوْمَ الْقِيَامَةِ ‏","","",""],[12361,12361,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَيْرَ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالَ فَقَالَ ذَاكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[12362,12362,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ يُوسُفَ يَعْنِي الْمِسْمَعِيَّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَلِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏يَوْمَانِ يَلْعَبُونَ فِيهِمَا فَقَالَ ‏ ‏قَدِمْتُ عَلَيْكُمْ وَلَكُمْ يَوْمَانِ تَلْعَبُونَ فِيهِمَا فَإِنَّ اللَّهَ قَدْ أَبْدَلَكُمْ يَوْمَيْنِ خَيْرًا مِنْهُمَا يَوْمَ الْفِطْرِ ‏ ‏وَيَوْمَ النَّحْرِ ‏","","",""],[12363,12363,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏هَلْ ‏ ‏خَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏لَمْ يَشِنْهُ الشَّيْبُ قَالَ فَقِيلَ يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏وَشَيْنٌ هُوَ قَالَ يُقَالُ كُلُّكُمْ يَكْرَهُهُ ‏ ‏وَخَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏ ‏وَخَضَبَ ‏ ‏عُمَرُ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[12364,12364,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏اطَّلَعَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏خَلَلٍ ‏ ‏فَسَدَّدَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِشْقَصٍ ‏ ‏فَأَخْرَجَ الرَّجُلُ رَأْسَهُ ‏","","",""],[12365,12365,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَسْنَدَاهُ جَمِيعًا عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏","","",""],[12366,12366,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُجَّ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَكَسَرُوا ‏ ‏رَبَاعِيَتَهُ ‏ ‏فَجَعَلَ يَمْسَحُ الدَّمَ عَنْ وَجْهِهِ وَهُوَ يَقُولُ ‏ ‏كَيْفَ يُفْلِحُ قَوْمٌ خَضَّبُوا وَجْهَ نَبِيِّهِمْ بِالدَّمِ وَهُوَ يَدْعُوهُمْ إِلَى رَبِّهِمْ عَزَّ وَجَلَّ فَأُنْزِلَتْ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[12367,12367,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَوْمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَطَوُّعًا قَالَ كَانَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ ‏","","",""],[12368,12368,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْكَسَلِ وَالْبُخْلِ وَعَذَابِ الْقَبْرِ ‏","","",""],[12369,12369,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَرَأَيْتُ قَصْرًا مِنْ ذَهَبٍ قُلْتُ لِمَنْ هَذَا الْقَصْرُ قَالُوا لِشَابٍّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَظَنَنْتُ أَنِّي أَنَا هُوَ قَالُوا ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏","","",""],[12370,12370,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏اسْتَحْمَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَافَقَ مِنْهُ شُغْلًا قَالَ وَاللَّهِ ‏ ‏لَا أَحْمِلُكُمْ فَلَمَّا ‏ ‏قَفَّى ‏ ‏دَعَاهُ فَقَالَ حَلَفْتَ لَا تَحْمِلُنَا قَالَ وَأَنَا أَحْلِفُ لَأَحْمِلَنَّكُمْ فَحَمَلَهُمْ ‏","","",""],[12371,12371,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏قَالَ ‏ ‏اسْتَحْمَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَلَفَ ‏ ‏لَا يَحْمِلُنَا ثُمَّ حَمَلَنَا قُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ حَلَفْتَ لَا تَحْمِلُنَا قَالَ وَأَنَا أَحْلِفُ لَأَحْمِلَنَّكُمْ ‏","","",""],[12372,12372,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ جَنَازَةً مَرَّتْ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهَا خَيْرًا وَتَتَابَعَتْ ‏ ‏الْأَلْسُنُ لَهَا بِالْخَيْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ ثُمَّ مَرَّتْ جَنَازَةٌ أُخْرَى فَقَالُوا لَهَا شَرًّا وَتَتَابَعَتْ ‏ ‏الْأَلْسُنُ لَهَا بِالشَّرِّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ ‏ ‏أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الْأَرْضِ ‏","","",""],[12373,12373,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّبَيْرُ بْنُ عَدِيٍّ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏نَشْكُو إِلَيْهِ ‏ ‏الْحَجَّاجَ ‏ ‏فَقَالَ ‏ ‏لَا يَأْتِي عَلَيْكُمْ يَوْمٌ ‏ ‏أَوْ زَمَانٌ ‏ ‏إِلَّا الَّذِي بَعْدَهُ شَرٌّ مِنْهُ سَمِعْتُهُ مِنْ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12374,12374,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏ابْنِ جَبْرِ بْنِ عَتِيكٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُجْزِئُ فِي الْوُضُوءِ رَطْلَانِ مِنْ مَاءٍ ‏","","",""],[12375,12375,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ السَّبُعِ ‏","","",""],[12376,12376,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ فَإِنَّ مِنْ حُسْنِ الصَّلَاةِ إِقَامَةَ الصَّفِّ ‏","","",""],[12377,12377,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[12378,12378,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ شَاذَانُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ بِإِنَاءٍ يَكُونُ رَطْلَيْنِ وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏","","",""],[12379,12379,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى حَصِيرٍ ‏","","",""],[12380,12380,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏وَكَانُوا لَا يَجْهَرُونَ بْ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏","","",""],[12381,12381,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْصَرِفُ عَنْ يَمِينِهِ ‏","","",""],[12382,12382,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ وَرْدَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏","","",""],[12383,12383,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَصَمِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏لَا يَنْقُصُونَ التَّكْبِيرَ ‏","","",""],[12384,12384,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا يَدْعُو بَعْدَ الرُّكُوعِ ‏","","",""],[12385,12385,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ الضُّبَعِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ يُنَاوِلُ أَصْحَابَهُ وَهُمْ يَبْنُونَ ‏ ‏الْمَسْجِدَ ‏ ‏أَلَا إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[12386,12386,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَزَعٌ فَاسْتَعَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏يُقَالُ لَهُ مَنْدُوبٌ فَرَكِبَهُ ثُمَّ جَاءَ فَقَالَ ‏ ‏مَا رَأَيْنَا مِنْ فَزَعٍ وَإِنْ وَجَدْنَا لَبَحْرًا ‏","","",""],[12387,12387,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏مَكَّةَ ‏ ‏عَامَ الْفَتْحِ وَعَلَيْهِ ‏ ‏مِغْفَرٌ ‏","","",""],[12388,12388,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَخِيسِ الْيَشْكُرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ قَدْ اسْتُشْهِدَ مَوْلَاكَ فُلَانٌ قَالَ ‏ ‏كَلَّا إِنِّي رَأَيْتُ عَلَيْهِ عَبَاءَةً ‏ ‏غَلَّهَا ‏ ‏يَوْمَ كَذَا وَكَذَا ‏","","",""],[12389,12389,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَيْتَامٍ فِي حِجْرِهِ وَرِثُوا خَمْرًا أَنْ يَجْعَلَهَا خَلًّا فَكَرِهَ ذَلِكَ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً أَفَلَا يَجْعَلُهَا ‏","","",""],[12390,12390,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَزِّرُ ‏ ‏فِي الْخَمْرِ بِالنِّعَالِ وَالْجَرِيدِ ‏ ‏قَالَ ‏ ‏ثُمَّ ضَرَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَرْبَعِينَ ‏ ‏فَلَمَّا كَانَ زَمَنُ ‏ ‏عُمَرَ ‏ ‏وَدَنَا النَّاسُ مِنْ الرِّيفِ وَالْقُرَى اسْتَشَارَ فِي ذَلِكَ النَّاسَ وَفَشَا ذَلِكَ فِي النَّاسِ فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏أَرَى أَنْ تَجْعَلَهُ كَأَخَفِّ ‏ ‏الْحُدُودِ ‏ ‏فَضَرَبَ ‏ ‏عُمَرُ ‏ ‏ثَمَانِينَ ‏","","",""],[12391,12391,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى قَوْمٍ تُقْرَضُ شِفَاهُهُمْ بِمَقَارِيضَ مِنْ نَارٍ قُلْتُ مَا هَؤُلَاءِ قَالَ هَؤُلَاءِ خُطَبَاءُ أُمَّتِكَ مِنْ أَهْلِ الدُّنْيَا كَانُوا يَأْمُرُونَ النَّاسَ بِالْبِرِّ وَيَنْسَوْنَ أَنْفُسَهُمْ وَهُمْ يَتْلُونَ الْكِتَابَ أَفَلَا يَعْقِلُونَ ‏","","",""],[12392,12392,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏","","",""],[12393,12393,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ جَعْفَرٍ يَعْنِي غُنْدَرًا ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِلَحْمٍ ‏ ‏تُصُدِّقَ ‏ ‏بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[12394,12394,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ الْأَسَدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[12395,12395,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَجِئْتُ وَهُوَ يَأْكُلُ تَمْرًا وَهُوَ ‏ ‏مُقْعٍ ‏","","",""],[12396,12396,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ خَيَّاطًا دَعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى طَعَامٍ فَأَتَاهُ بِطَعَامٍ وَقَدْ جَعَلَهُ ‏ ‏بِإِهَالَةٍ ‏ ‏سَنِخَةٍ ‏ ‏وَقَرْعٍ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتْبَعُ الْقَرْعَ مِنْ الصَّحْفَةِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا زِلْتُ يُعْجِبُنِي الْقَرْعُ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏","","",""],[12397,12397,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏صَبْرِ ‏ ‏الْبَهِيمَةِ ‏","","",""],[12398,12398,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رُخِّصَ ‏ ‏لِلزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏فِي لُبْسِ الْحَرِيرِ ‏ ‏لِحِكَّةٍ ‏ ‏كَانَتْ بِهِمَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ رَخَّصَ لَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[12399,12399,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ أَنْ يَكْتُبَ كِتَابًا إِلَى ‏ ‏الرُّومِ ‏ ‏فَقِيلَ لَهُ إِنْ لَمْ يَكُنْ مَخْتُومًا لَمْ يُقْرَأْ كِتَابُكَ ‏ ‏فَاتَّخَذَ خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏وَنَقَشَ فِيهِ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ فَكَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي كَفِّهِ ‏","","",""],[12400,12400,"","","‏ ‏حَدَّثَنَا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَرَأْتُ عَلَى أَبِي هَذَا الْحَدِيثَ وَجَدَهُ فَأَقَرَّ بِهِ وَحَدَّثَنَا بِبَعْضِهِ فِي مَكَانٍ آخَرَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ هِلَالٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَهِيَ أُمُّ ‏ ‏أَنَسٍ ‏ ‏وَالْبَرَاءِ ‏ ‏قَالَ فَوَلَدَتْ لَهُ ‏ ‏ابْنًا ‏ ‏قَالَ فَكَانَ يُحِبُّهُ حُبًّا شَدِيدًا قَالَ فَمَرِضَ ‏ ‏الصَّبِيُّ ‏ ‏مَرَضًا شَدِيدًا فَكَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَقُومُ صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏يَتَوَضَّأُ وَيَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُصَلِّي مَعَهُ وَيَكُونُ مَعَهُ إِلَى قَرِيبٍ مِنْ نِصْفِ النَّهَارِ وَيَجِيءُ ‏ ‏يَقِيلُ ‏ ‏وَيَأْكُلُ فَإِذَا صَلَّى الظُّهْرَ تَهَيَّأَ وَذَهَبَ فَلَمْ يَجِئْ إِلَى صَلَاةِ ‏ ‏الْعَتَمَةِ ‏ ‏قَالَ فَرَاحَ عَشِيَّةً وَمَاتَ الصَّبِيُّ قَالَ وَجَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏قَالَ نَسَجَتْ عَلَيْهِ ثَوْبًا وَتَرَكَتْهُ قَالَ فَقَالَ لَهَا ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏كَيْفَ بَاتَ بُنَيَّ اللَّيْلَةَ قَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏مَا كَانَ ابْنُكَ مُنْذُ ‏ ‏اشْتَكَى ‏ ‏أَسْكَنَ مِنْهُ اللَّيْلَةَ قَالَ ثُمَّ جَاءَتْهُ بِالطَّعَامِ فَأَكَلَ وَطَابَتْ نَفْسُهُ قَالَ فَقَامَ إِلَى فِرَاشِهِ فَوَضَعَ رَأْسَهُ قَالَتْ وَقُمْتُ أَنَا فَمَسِسْتُ شَيْئًا مِنْ طِيبٍ ثُمَّ جِئْتُ حَتَّى دَخَلْتُ مَعَهُ الْفِرَاشَ فَمَا هُوَ إِلَّا أَنْ وَجَدَ رِيحَ الطِّيبِ كَانَ مِنْهُ مَا يَكُونُ مِنْ الرَّجُلِ إِلَى أَهْلِهِ قَالَ ثُمَّ أَصْبَحَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَتَهَيَّأُ كَمَا كَانَ يَتَهَيَّأُ كُلَّ يَوْمٍ قَالَ فَقَالَتْ لَهُ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏أَرَأَيْتَ لَوْ أَنَّ رَجُلًا اسْتَوْدَعَكَ وَدِيعَةً فَاسْتَمْتَعْتَ بِهَا ثُمَّ طَلَبَهَا فَأَخَذَهَا مِنْكَ ‏ ‏تَجْزَعُ ‏ ‏مِنْ ذَلِكَ قَالَ لَا قَالَتْ فَإِنَّ ابْنَكَ قَدْ مَاتَ قَالَ ‏ ‏أَنَسٌ ‏ ‏فَجَزِعَ ‏ ‏عَلَيْهِ ‏ ‏جَزَعًا ‏ ‏شَدِيدًا وَحَدَّثَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا كَانَ مِنْ أَمْرِهَا فِي الطَّعَامِ وَالطِّيبِ وَمَا كَانَ مِنْهُ إِلَيْهَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبِتُّمَا عَرُوسَيْنِ وَهُوَ إِلَى جَنْبِكُمَا قَالَ نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَارَكَ اللَّهُ لَكُمَا فِي لَيْلَتِكُمَا قَالَ فَحَمَلَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏تِلْكَ اللَّيْلَةَ قَالَ فَتَلِدُ غُلَامًا قَالَ فَحِينَ أَصْبَحْنَا قَالَ لِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏احْمِلْهُ فِي خِرْقَةٍ حَتَّى تَأْتِيَ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاحْمِلْ مَعَكَ تَمْرَ عَجْوَةٍ قَالَ فَحَمَلْتُهُ فِي خِرْقَةٍ قَالَ وَلَمْ ‏ ‏يُحَنَّكْ ‏ ‏وَلَمْ يَذُقْ طَعَامًا وَلَا شَيْئًا قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ وَلَدَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏قَالَ اللَّهُ أَكْبَرُ مَا وَلَدَتْ قُلْتُ غُلَامًا قَالَ الْحَمْدُ لِلَّهِ فَقَالَ هَاتِهِ إِلَيَّ فَدَفَعْتُهُ إِلَيْهِ ‏ ‏فَحَنَّكَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَهُ مَعَكَ تَمْرُ عَجْوَةٍ قُلْتُ نَعَمْ فَأَخْرَجْتُ تَمَرَاتٍ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرَةً وَأَلْقَاهَا فِي ‏ ‏فِيهِ فَمَا زَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلُوكُهَا ‏ ‏حَتَّى اخْتَلَطَتْ بِرِيقِهِ ثُمَّ دَفَعَ الصَّبِيَّ فَمَا هُوَ إِلَّا أَنْ وَجَدَ الصَّبِيُّ حَلَاوَةَ التَّمْرِ جَعَلَ يَمُصُّ بَعْضَ حَلَاوَةِ التَّمْرِ وَرِيقَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ أَوَّلُ مَنْ فَتَحَ أَمْعَاءَ ذَلِكَ الصَّبِيِّ عَلَى رِيقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِبُّ ‏ ‏الْأَنْصَارِ ‏ ‏التَّمْرُ فَسُمِّيَ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي طَلْحَةَ ‏ ‏قَالَ فَخَرَجَ مِنْهُ رَجُلٌ كَثِيرٌ قَالَ وَاسْتُشْهِدَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏بِفَارِسَ ‏","","",""]];
